function avCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw Error('Unclosed CSV quote');if(cell||row.length){row.push(cell);rows.push(row);}const headers=rows.shift()?.map(x=>x.replace(/^\uFEFF/,'').trim());if(!headers?.includes('symbol')||!headers.includes('reportDate')||!headers.includes('fiscalDateEnding'))throw Error('Unexpected calendar CSV headers');return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??''])));}
