function twScope(e){return /full[_ -]?(article|text)|article[_ -]text|primary[_ -]?page/i.test(e.evidence_scope||'')?'public article excerpt':'headline/feed excerpt';}
function twStocks(e){return [...new Set([...(e.analysis?.impacts||[]).map(p=>p.stock_id),...(e.candidates||[]).map(m=>m.stock_id)])];}
function twChecks(e){
